// plugins/lib/context.ts
import { appendFileSync } from "fs";
import { join } from "path";
import { execSync } from "child_process";

// package.json
var name = "@fiandev/opencode-kit";
var version = "2.2.0";

// plugins/includes/constants.ts
var PACKAGE_NAME = name;
var CURRENT_VERSION = version;
var FALLBACK_MODEL = "opencode-go/deepseek-v4.1-flash-free";
var READ_ONLY_AGENTS = [
  "orchestrator",
  "analyst",
  "architect",
  "tester",
  "reviewer",
  "security",
  "pentester",
  "pr-reviewer",
  "version-analyzer"
];

// plugins/lib/errors.ts
function errorMessage(error) {
  if (error instanceof Error)
    return error.message;
  if (typeof error === "string")
    return error;
  return "Unknown error";
}
function errorOutput(error) {
  const stderr = error?.stderr;
  if (stderr !== undefined && stderr !== null) {
    const output = String(stderr).trim();
    if (output !== "")
      return output;
  }
  return errorMessage(error);
}

// plugins/lib/context.ts
var createPluginContext = ({ directory, log }) => {
  const normalizedLog = log ?? (() => {});
  const baseDirectory = directory || process.cwd();
  const runCommand = (cmd, cwd) => {
    try {
      const output = execSync(cmd, {
        encoding: "utf-8",
        cwd: cwd || baseDirectory,
        stdio: ["pipe", "pipe", "pipe"]
      });
      return { success: true, output: output.trim() };
    } catch (error) {
      return { success: false, output: "", error: errorOutput(error) };
    }
  };
  const getGitRoot = (basePath) => {
    const result = runCommand("git rev-parse --show-toplevel", basePath || baseDirectory);
    if (!result.success) {
      throw new Error(`Not a git repository or git not found: ${result.error}`);
    }
    return result.output.replace(/\\/g, "/");
  };
  const getCurrentBranch = (basePath) => {
    const result = runCommand("git symbolic-ref --short HEAD", basePath || baseDirectory);
    return result.success ? result.output : "main";
  };
  const logEvent = (level, message, context) => {
    try {
      const gitRoot = getGitRoot(baseDirectory);
      const logFile = join(gitRoot, ".agent-logs.jsonl");
      const logEntry = JSON.stringify({
        timestamp: new Date().toISOString(),
        level,
        message,
        context
      }) + `
`;
      appendFileSync(logFile, logEntry);
    } catch (error) {
      console.error("Failed to write log:", error);
    }
  };
  const checkForUpdates = async () => {
    try {
      const result = runCommand(`npm view ${PACKAGE_NAME} version`);
      if (result.success) {
        const latestVersion = result.output.trim();
        return {
          hasUpdate: latestVersion !== CURRENT_VERSION,
          current: CURRENT_VERSION,
          latest: latestVersion
        };
      }
    } catch {}
    return { hasUpdate: false, current: CURRENT_VERSION, latest: CURRENT_VERSION };
  };
  return {
    baseDirectory,
    log: normalizedLog,
    runCommand,
    getGitRoot,
    getCurrentBranch,
    logEvent,
    checkForUpdates
  };
};

// plugins/lib/guard.ts
import { basename } from "path";

// plugins/lib/registry.ts
var agentPermissions = new Map;
var setAgentPermissions = (sessionID, permissions) => {
  agentPermissions.set(sessionID, permissions);
};
var getAgentPermissions = (sessionID) => {
  return agentPermissions.get(sessionID);
};
var deleteAgentPermissions = (sessionID) => {
  return agentPermissions.delete(sessionID);
};
var hasAgentPermissions = (sessionID) => {
  return agentPermissions.has(sessionID);
};

// plugins/lib/glob.ts
function matchGlob(path, pattern) {
  const normalizedPath = path.replace(/\\/g, "/");
  const normalizedPattern = pattern.replace(/\\/g, "/");
  const regexPattern = normalizedPattern.replace(/\*\*/g, "{{DOUBLESTAR}}").replace(/\*/g, "[^/]*").replace(/{{DOUBLESTAR}}/g, ".*").replace(/\//g, "\\/");
  const regex = new RegExp(`^${regexPattern}$`);
  return regex.test(normalizedPath);
}

// plugins/lib/util.ts
import { readFileSync, existsSync } from "fs";
import { join as join2 } from "path";
function readWorktreeBranch(worktreePath) {
  const taskFile = join2(worktreePath, ".agent-task");
  if (!existsSync(taskFile))
    return;
  const match = readFileSync(taskFile, "utf-8").match(/^# Branch:\s*(.+)$/m);
  return match?.[1]?.trim();
}
function firstString(...values) {
  for (const value of values) {
    if (typeof value === "string" && value !== "")
      return value;
  }
  return;
}

// plugins/lib/guard.ts
var DANGEROUS_BASH_PATTERNS = [
  /\becho\s+.*>/,
  /\bcat\s+.*>/,
  /\brm\s+/,
  /\bmv\s+/,
  /\bcp\s+/,
  /\bmkdir\s+/,
  /\btouch\s+/,
  /\bnpm\s+install/,
  /\bgit\s+commit/,
  /\bgit\s+push/,
  /\bgit\s+tag\s+(?:-a|-s|-d|-f|-u|-m|--delete|--force|--annotate|--sign)/,
  /\bgit\s+tag\s+[^\s-]/
];
var createToolBeforeGuard = (ctx) => {
  return async (input, output) => {
    const perms = getAgentPermissions(input.sessionID);
    if (!perms)
      return;
    const toolName = input.tool;
    const args = output.args ?? {};
    if (["edit", "write", "patch", "multiedit"].includes(toolName)) {
      if (!perms.canEdit) {
        ctx.logEvent("warn", `BLOCKED: ${perms.type} tried to use ${toolName}`, { sessionID: input.sessionID });
        throw new Error(`BLOCKED ${perms.type} is read-only`);
      }
      const targetPath = firstString(args.filePath, args.file_path, args.path);
      if (targetPath) {
        if (perms.deniedPaths.some((denied) => targetPath.includes(denied) || matchGlob(targetPath, denied))) {
          ctx.logEvent("warn", `BLOCKED: ${perms.type} tried to edit denied path`, { sessionID: input.sessionID, path: targetPath });
          throw new Error(`BLOCKED Path denied: ${basename(targetPath)}`);
        }
        if (perms.allowedPaths && perms.allowedPaths.length > 0) {
          const isAllowed = perms.allowedPaths.some((allowed) => targetPath.includes(allowed) || matchGlob(targetPath, allowed));
          if (!isAllowed) {
            ctx.logEvent("warn", `BLOCKED: ${perms.type} tried to edit outside allowed paths`, { sessionID: input.sessionID, path: targetPath });
            throw new Error(`BLOCKED Outside allowed paths: ${basename(targetPath)}`);
          }
        }
      }
    }
    if (toolName === "bash" && !perms.canEdit) {
      const cmd = typeof args.command === "string" ? args.command : "";
      for (const pattern of DANGEROUS_BASH_PATTERNS) {
        if (pattern.test(cmd)) {
          ctx.logEvent("warn", `BLOCKED: ${perms.type} tried dangerous bash command`, { sessionID: input.sessionID });
          throw new Error(`BLOCKED ${perms.type} is read-only`);
        }
      }
    }
    if (toolName === "bash" && perms.worktree) {
      const command = typeof args.command === "string" ? args.command : "";
      if (command !== "") {
        const worktreePath = perms.worktree.replace(/\\/g, "/");
        output.args.command = `cd "${worktreePath}" && ${command}`;
      }
    }
  };
};

// plugins/tools/worktree.ts
import { readFileSync as readFileSync2, existsSync as existsSync2, readdirSync, statSync, mkdirSync, writeFileSync, unlinkSync, appendFileSync as appendFileSync2 } from "fs";
import { join as join3 } from "path";

// plugins/lib/tool.ts
import { z } from "zod";
var tool = Object.assign((definition) => definition, { schema: z });

// plugins/tools/worktree.ts
var worktreeTools = (ctx) => ({
  worktree_create: tool({
    description: `Create a new git worktree branch for parallel development.
Use this to set up isolated development environments for subtasks.
Each worktree has its own branch and working directory.`,
    args: {
      branch: tool.schema.string().describe("Branch name for the worktree (e.g., 'feat/auth-login')"),
      task: tool.schema.string().describe("Description of the task to be done in this worktree")
    },
    async execute(args) {
      try {
        const { branch, task } = args;
        if (!branch || branch.trim() === "") {
          ctx.logEvent("error", "worktree_create failed: empty branch name");
          return "ERROR Branch name required";
        }
        if (!task || task.trim() === "") {
          ctx.logEvent("error", "worktree_create failed: empty task description");
          return "ERROR Task description required";
        }
        const gitRoot = ctx.getGitRoot();
        const baseBranch = ctx.getCurrentBranch();
        const sessionName = branch.replace(/\//g, "-");
        const worktreeDir = join3(gitRoot, "worktrees");
        const worktreePath = join3(worktreeDir, sessionName);
        if (existsSync2(worktreePath)) {
          ctx.logEvent("warn", "Worktree already exists", { branch, path: worktreePath });
          return `WARN Worktree exists: ${sessionName}`;
        }
        ctx.logEvent("info", "Creating worktree", { branch, baseBranch });
        const gitignorePath = join3(gitRoot, ".gitignore");
        const gitignoreContent = existsSync2(gitignorePath) ? readFileSync2(gitignorePath, "utf-8") : "";
        if (!gitignoreContent.includes(".agent-")) {
          const additions = `
# Agent files (never commit)
.agent-task
.agent-done
.agent-blocked
.agent-error
.agent-logs.jsonl

# Worktrees directory
worktrees/
`;
          appendFileSync2(gitignorePath, additions);
          ctx.runCommand(`git add "${gitignorePath}" && git commit -m "chore: add agent files to gitignore"`, gitRoot);
        }
        try {
          mkdirSync(worktreeDir, { recursive: true });
        } catch (error) {
          ctx.logEvent("error", "Failed to create worktree directory", { error: errorMessage(error) });
          return `ERROR mkdir failed: ${errorMessage(error)}`;
        }
        const branchCheckResult = ctx.runCommand(`git rev-parse --verify ${branch}`);
        const branchExists = branchCheckResult.success;
        const worktreeCmd = branchExists ? `git worktree add "${worktreePath}" ${branch}` : `git worktree add -b ${branch} "${worktreePath}" ${baseBranch}`;
        const worktreeResult = ctx.runCommand(worktreeCmd, gitRoot);
        if (!worktreeResult.success) {
          ctx.logEvent("error", "Failed to create git worktree", {
            branch,
            command: worktreeCmd,
            error: worktreeResult.error
          });
          return `ERROR git worktree failed: ${worktreeResult.error}`;
        }
        const taskContent = `# Agent Task
# Branch: ${branch}
# Created: ${new Date().toISOString()}
# Base: ${baseBranch}

${task}
`;
        try {
          writeFileSync(join3(worktreePath, ".agent-task"), taskContent);
        } catch (error) {
          ctx.logEvent("warn", "Failed to write task file", { error: errorMessage(error) });
        }
        ctx.logEvent("info", "Worktree created successfully", { branch, path: worktreePath });
        return `OK Worktree: ${sessionName} (${branch})`;
      } catch (error) {
        ctx.logEvent("error", "worktree_create exception", {
          error: errorMessage(error),
          stack: error instanceof Error ? error.stack : undefined
        });
        return `ERROR Error: ${errorMessage(error)}`;
      }
    }
  }),
  status: tool({
    description: `Get the status of all worktrees and their development progress.
Shows which tasks are done, in progress, blocked, or have errors.`,
    args: {},
    async execute() {
      const gitRoot = ctx.getGitRoot();
      const worktreeDir = join3(gitRoot, "worktrees");
      if (!existsSync2(worktreeDir)) {
        return "No worktrees";
      }
      const entries = readdirSync(worktreeDir);
      if (entries.length === 0) {
        return "No worktrees";
      }
      let total = 0, done = 0, blocked = 0, errors = 0, wip = 0;
      let rows = [];
      for (const entry of entries) {
        const wpath = join3(worktreeDir, entry);
        if (!statSync(wpath).isDirectory())
          continue;
        total++;
        const doneFile = join3(wpath, ".agent-done");
        const blockedFile = join3(wpath, ".agent-blocked");
        const errorFile = join3(wpath, ".agent-error");
        let icon = "WIP";
        if (existsSync2(doneFile)) {
          icon = "OK";
          done++;
        } else if (existsSync2(blockedFile)) {
          icon = "BLOCKED";
          blocked++;
        } else if (existsSync2(errorFile)) {
          icon = "ERROR";
          errors++;
        } else {
          wip++;
        }
        rows.push(`${icon} ${entry}`);
      }
      return `${rows.join(`
`)}
---
Total:${total} Done:${done} WIP:${wip} Blocked:${blocked} Err:${errors}`;
    }
  }),
  merge: tool({
    description: `Merge a completed worktree branch back into the current branch.
Only merges if the worktree is marked as done (.agent-done exists).
Handles merge conflicts by reporting them.`,
    args: {
      worktree: tool.schema.string().describe("Worktree session name to merge (e.g., 'feat-auth-login')")
    },
    async execute(args) {
      const gitRoot = ctx.getGitRoot();
      const worktreePath = join3(gitRoot, "worktrees", args.worktree);
      const doneFile = join3(worktreePath, ".agent-done");
      if (!existsSync2(worktreePath)) {
        return `ERROR Not found: ${args.worktree}`;
      }
      if (!existsSync2(doneFile)) {
        return `ERROR Not done: ${args.worktree}`;
      }
      const branch = readWorktreeBranch(worktreePath) ?? args.worktree;
      const result = ctx.runCommand(`git merge --no-ff "${branch}" --no-edit`, gitRoot);
      if (result.success) {
        return `OK Merged: ${branch}`;
      } else {
        const output = result.error || "";
        if (output.includes("CONFLICT")) {
          return `WARN Conflict in ${branch}`;
        }
        return `ERROR Merge failed: ${output.slice(0, 100)}`;
      }
    }
  }),
  cleanup: tool({
    description: `Remove completed or abandoned worktrees to clean up disk space.
Removes the worktree directory and prunes git worktree references.`,
    args: {
      worktree: tool.schema.string().describe("Worktree session name to cleanup (e.g., 'feat-auth-login')"),
      force: tool.schema.boolean().optional().describe("Force cleanup even if not marked as done")
    },
    async execute(args) {
      const gitRoot = ctx.getGitRoot();
      const worktreePath = join3(gitRoot, "worktrees", args.worktree);
      const doneFile = join3(worktreePath, ".agent-done");
      if (!existsSync2(worktreePath)) {
        return `ERROR Not found: ${args.worktree}`;
      }
      if (!args.force && !existsSync2(doneFile)) {
        return `ERROR Not done (use force=true)`;
      }
      const removeResult = ctx.runCommand(`git worktree remove "${worktreePath}" --force`, gitRoot);
      if (!removeResult.success) {
        return `ERROR ${removeResult.error}`;
      }
      ctx.runCommand("git worktree prune", gitRoot);
      return `OK Cleaned: ${args.worktree}`;
    }
  }),
  done: tool({
    description: `Mark a worktree task as completed. Creates the .agent-done file with a summary.
Use this when you've finished implementing the task in a worktree.`,
    args: {
      worktree: tool.schema.string().describe("Worktree session name"),
      summary: tool.schema.string().describe("Brief summary of what was accomplished")
    },
    async execute(args) {
      const gitRoot = ctx.getGitRoot();
      const worktreePath = join3(gitRoot, "worktrees", args.worktree);
      if (!existsSync2(worktreePath)) {
        return `ERROR Not found: ${args.worktree}`;
      }
      writeFileSync(join3(worktreePath, ".agent-done"), `${args.summary}
`);
      for (const marker of [".agent-error", ".agent-blocked"]) {
        const markerPath = join3(worktreePath, marker);
        if (existsSync2(markerPath))
          unlinkSync(markerPath);
      }
      return `OK Done: ${args.worktree}`;
    }
  }),
  blocked: tool({
    description: `Mark a worktree task as blocked. Creates the .agent-blocked file with the reason.
Use this when you cannot proceed due to missing information or dependencies.`,
    args: {
      worktree: tool.schema.string().describe("Worktree session name"),
      reason: tool.schema.string().describe("Why the task is blocked")
    },
    async execute(args) {
      const gitRoot = ctx.getGitRoot();
      const worktreePath = join3(gitRoot, "worktrees", args.worktree);
      if (!existsSync2(worktreePath)) {
        return `ERROR Not found: ${args.worktree}`;
      }
      writeFileSync(join3(worktreePath, ".agent-blocked"), `${args
…[文件过长——中段 8KB 抽样]…
    let errorMessages = "";
      const doCheck = (label, cmd) => {
        const result = ctx.runCommand(cmd, worktreePath);
        if (result.success) {
          passed.push(label);
        } else {
          failed.push(label);
          errorMessages += `${label}: ${result.error?.slice(0, 200)}
`;
        }
      };
      const packageJson = join4(worktreePath, "package.json");
      const goMod = join4(worktreePath, "go.mod");
      const cargoToml = join4(worktreePath, "Cargo.toml");
      const pyProject = join4(worktreePath, "pyproject.toml");
      const requirements = join4(worktreePath, "requirements.txt");
      if (existsSync3(packageJson)) {
        const pkg = JSON.parse(readFileSync3(packageJson, "utf-8"));
        if (pkg.scripts?.lint)
          doCheck("lint", "npm run lint");
        if (pkg.scripts?.build)
          doCheck("build", "npm run build");
        if (pkg.scripts?.test)
          doCheck("test", "npm test");
      }
      if (existsSync3(goMod)) {
        doCheck("go-build", "go build ./...");
        doCheck("go-test", "go test ./...");
      }
      if (existsSync3(cargoToml)) {
        doCheck("cargo-check", "cargo check");
        doCheck("cargo-test", "cargo test");
      }
      if (existsSync3(pyProject) || existsSync3(requirements)) {
        doCheck("pytest", "pytest");
      }
      if (failed.length > 0) {
        writeFileSync2(join4(worktreePath, ".agent-error"), errorMessages);
        const doneFile = join4(worktreePath, ".agent-done");
        if (existsSync3(doneFile))
          unlinkSync2(doneFile);
        return `ERROR Failed: ${failed.join(", ")}${passed.length ? ` | OK ${passed.join(", ")}` : ""}`;
      }
      if (passed.length === 0)
        return "WARN No checks found";
      return `OK All passed: ${passed.join(", ")}`;
    }
  }),
  final_check: tool({
    description: `Run global build/lint checks on the main project after all merges.
Compares errors against files modified during the session.`,
    args: {
      baseCommit: tool.schema.string().optional().describe("The commit SHA from before the session started.")
    },
    async execute(args) {
      try {
        const gitRoot = ctx.getGitRoot();
        let baseCommit = args.baseCommit;
        if (!baseCommit) {
          const reflogResult = ctx.runCommand('git reflog --format="%H %gs" -n 50', gitRoot);
          if (reflogResult.success) {
            const lines = reflogResult.output.split(`
`);
            for (const line of lines) {
              if (!line.includes("merge") || !line.includes("feat-") && !line.includes("fix-")) {
                baseCommit = line.split(" ")[0];
                break;
              }
            }
          }
          if (!baseCommit)
            baseCommit = "HEAD~10";
        }
        const diffResult = ctx.runCommand(`git diff ${baseCommit}..HEAD --name-only`, gitRoot);
        const modifiedFiles = diffResult.success ? diffResult.output.split(`
`).filter((f) => f.trim()).map((f) => f.trim()) : [];
        const packageJson = join4(gitRoot, "package.json");
        const goMod = join4(gitRoot, "go.mod");
        const cargoToml = join4(gitRoot, "Cargo.toml");
        const pyProject = join4(gitRoot, "pyproject.toml");
        let passed = [];
        let failed = [];
        let sessionErrors = 0;
        let preExistingErrors = 0;
        const runCheck = (name, cmd) => {
          const result = ctx.runCommand(`${cmd} 2>&1`, gitRoot);
          if (result.success) {
            passed.push(name);
          } else {
            failed.push(name);
            const output = result.error || result.output;
            const lines = output.split(`
`);
            for (const line of lines) {
              const match = line.match(/^(.+?):(\d+)/);
              const file = match?.[1]?.replace(/\\/g, "/");
              if (file) {
                if (modifiedFiles.some((mf) => file.includes(mf) || mf.includes(file))) {
                  sessionErrors++;
                } else {
                  preExistingErrors++;
                }
              }
            }
          }
        };
        if (existsSync3(packageJson)) {
          const pkg = JSON.parse(readFileSync3(packageJson, "utf-8"));
          if (pkg.scripts?.lint)
            runCheck("lint", "npm run lint");
          if (pkg.scripts?.build)
            runCheck("build", "npm run build");
          if (pkg.scripts?.typecheck)
            runCheck("typecheck", "npm run typecheck");
        }
        if (existsSync3(goMod)) {
          runCheck("go-build", "go build ./...");
          runCheck("go-vet", "go vet ./...");
        }
        if (existsSync3(cargoToml)) {
          runCheck("cargo", "cargo check");
        }
        if (existsSync3(pyProject)) {
          runCheck("ruff", "ruff check .");
        }
        if (passed.length === 0 && failed.length === 0) {
          return "WARN No checks found";
        }
        if (failed.length === 0) {
          return `OK All passed: ${passed.join(", ")}`;
        }
        let result = `ERROR Failed: ${failed.join(", ")}`;
        if (passed.length)
          result += ` | OK ${passed.join(", ")}`;
        if (sessionErrors)
          result += ` | Session errors: ${sessionErrors}`;
        if (preExistingErrors)
          result += ` | Pre-existing: ${preExistingErrors}`;
        return result;
      } catch (error) {
