import { Plugin } from "@opencode/plugin";
import { z as z2 } from "zod";
var MultiAgentDevPlugin = Plugin.define({
  id: "fiandev.opencode-kit",
  async setup(ctx) {
    const hooks = await createPluginHooks({
      directory: ctx.location.directory,
      log: (message) => console.debug(`[opencode-kit] ${message}`)
    });
    const tools = Object.entries(hooks.tool).map(([name, definition]) => ({
      name,
      definition,
      input: z2.toJSONSchema(z2.object(definition.args), { io: "input" })
    }));
    await ctx.tool.transform((editor) => {
      for (const { name, definition, input } of tools) {
        editor.add({
          name,
          description: definition.description,
          input,
          async execute(args) {
            return { content: await definition.execute(args, {}) };
          }
        });
      }
    });
    const before = hooks["tool.execute.before"];
    if (before) {
      await ctx.tool.hook("execute.before", async (event) => {
        const args = event.input && typeof event.input === "object" ? event.input : {};
        await before({ tool: event.tool, sessionID: event.sessionID, callID: event.id }, { args });
        if (event.input !== args)
          event.input = args;
      });
    }
    const chatParams = hooks["chat.params"];
    if (chatParams) {
      await ctx.session.hook("context", (event) => chatParams({ model: event.model }, event));
    }
    const controller = new AbortController;
    (async () => {
      try {
        for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
          await hooks.event?.({ event });
        }
      } catch (error) {
        if (!controller.signal.aborted) {
          console.error("opencode-kit: event subscription failed", error);
        }
      }
    })();
    return () => controller.abort();
  }
